if (inFlightTasks >= HIGH_WATERMARK && !isPaused) {
  consumer.pause(consumer.assignments());
  isPaused = true;
}

workerPool.onTaskComplete(() => {
  inFlightTasks--;
  if (inFlightTasks <= LOW_WATERMARK && isPaused) {
    consumer.resume(consumer.assignments());
    isPaused = false;
  }
});
